"""Small synthetic images of shapes, with labels, boxes and masks. No downloads.

make_shapes(n, classes, seed, setting) returns a dict of tensors:
  images (n, 3, 32, 32) float32 in [0, 1]; labels (n,) int64, indexes into `classes`;
  boxes (n, 4) float32 as (x1, y1, x2, y2) in pixels; masks (n, 32, 32) int64, 0 for background, 1 + label inside.
setting="studio": centred shapes of similar size, upright, on light backgrounds, with little noise.
setting="field": shapes anywhere, larger or smaller, tilted up to about 30 degrees, on darker backgrounds in
  uneven light, with more noise.
"""

import numpy as np
import torch

SIZE = 32
BASIC = ["circle", "square", "triangle"]


def _polygon(u, v, pts):
    """Even-odd rule: True where (u, v) is inside the polygon with vertices pts."""
    inside = np.zeros_like(u, dtype=bool)
    for (x1, y1), (x2, y2) in zip(pts, pts[1:] + pts[:1]):
        crosses = (y1 > v) != (y2 > v)
        x_at = (x2 - x1) * (v - y1) / (y2 - y1 + 1e-12) + x1
        inside ^= crosses & (u < x_at)
    return inside


def shape_mask(kind, cx, cy, r, angle):
    yy, xx = np.mgrid[0:SIZE, 0:SIZE] + 0.5
    c, s = np.cos(angle), np.sin(angle)
    u, v = c * (xx - cx) + s * (yy - cy), -s * (xx - cx) + c * (yy - cy)
    d = np.hypot(u, v)
    if kind == "circle":
        return d <= r
    if kind == "ring":
        return (d <= r) & (d >= 0.55 * r)
    if kind == "square":
        return (np.abs(u) <= 0.85 * r) & (np.abs(v) <= 0.85 * r)
    if kind == "triangle":
        return _polygon(u, v, [(0.0, -r), (0.95 * r, 0.75 * r), (-0.95 * r, 0.75 * r)])
    if kind == "cross":
        return ((np.abs(u) <= 0.3 * r) & (np.abs(v) <= r)) | ((np.abs(v) <= 0.3 * r) & (np.abs(u) <= r))
    if kind == "crescent":
        return (d <= r) & (np.hypot(u - 0.5 * r, v) > 0.8 * r)
    if kind == "star":
        pts = [((r if k % 2 == 0 else 0.45 * r) * np.sin(k * np.pi / 5), -(r if k % 2 == 0 else 0.45 * r) * np.cos(k * np.pi / 5))
               for k in range(10)]
        return _polygon(u, v, pts)
    if kind == "l_shape":
        return ((u >= -r) & (u <= -0.35 * r) & (np.abs(v) <= r)) | ((np.abs(u) <= r) & (v >= 0.35 * r) & (v <= r))
    if kind == "t_shape":
        return ((np.abs(u) <= r) & (v >= -r) & (v <= -0.35 * r)) | ((np.abs(u) <= 0.3 * r) & (np.abs(v) <= r))
    raise ValueError(kind)


def make_shapes(n, classes=BASIC, seed=0, setting="studio"):
    rng = np.random.default_rng(seed)
    field = setting == "field"
    images = np.empty((n, 3, SIZE, SIZE), dtype=np.float32)
    labels = rng.integers(0, len(classes), n)
    boxes = np.empty((n, 4), dtype=np.float32)
    masks = np.zeros((n, SIZE, SIZE), dtype=np.int64)
    gx = np.linspace(-1, 1, SIZE)
    for i in range(n):
        r = rng.uniform(6, 11) if field else rng.uniform(7, 9)
        if field:
            cx, cy = rng.uniform(r + 1, SIZE - r - 1, 2)
        else:
            cx, cy = SIZE / 2 + rng.uniform(-2, 2, 2)
        angle = rng.uniform(-0.5, 0.5) if field else rng.uniform(-0.15, 0.15)
        m = shape_mask(classes[labels[i]], cx, cy, r, angle)
        bg = rng.uniform(0.0, 0.6, 3) if field else rng.uniform(0.6, 0.9, 3)
        fg = rng.uniform(0.0, 1.0, 3)
        while np.abs(fg - bg).sum() < 0.6:              # keep the shape visible
            fg = rng.uniform(0.0, 1.0, 3)
        img = np.where(m, fg[:, None, None], bg[:, None, None])
        if field:                                       # light falling off towards one side
            t = rng.uniform(0, 2 * np.pi)
            img = img * (1 + rng.uniform(-0.3, 0.3) * (np.cos(t) * gx[None, :] + np.sin(t) * gx[:, None]))
        img = img + rng.normal(0, 0.08 if field else 0.03, img.shape)
        images[i] = np.clip(img, 0, 1)
        ys, xs = np.nonzero(m)
        boxes[i] = [xs.min(), ys.min(), xs.max() + 1, ys.max() + 1]
        masks[i][m] = labels[i] + 1
    return {"images": torch.from_numpy(images), "labels": torch.from_numpy(labels),
            "boxes": torch.from_numpy(boxes), "masks": torch.from_numpy(masks)}


if __name__ == "__main__":
    kinds = ["circle", "ring", "square", "triangle", "cross", "crescent", "star", "l_shape", "t_shape"]
    for k in kinds:                                     # print each shape at a fixed size as ASCII
        m = shape_mask(k, 16, 16, 10, 0.0)[4:28:2, 4:28]
        print(k, int(m.sum()))
    d = make_shapes(4, seed=1, setting="field")
    print(d["images"].shape, d["labels"].tolist(), d["boxes"][0].tolist())

